import{z as n,x as p,o as t,c as A,q as E,j as r,D as e,d as i,s as o,S as s}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"供应链集中与单一来源","description":"","frontmatter":{"title":"供应链集中与单一来源","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/supply-chain-single-source.md","filePath":"litho/supply-chain-single-source.md","lastUpdated":1791063341000}'),B={name:"litho/supply-chain-single-source.md"};function d(h,a,c,_,u,m){const l=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=E('<h1 id="供应链集中与单一来源" tabindex="-1">供应链集中与单一来源 <a class="header-anchor" href="#供应链集中与单一来源" aria-label="Permalink to &quot;供应链集中与单一来源&quot;">​</a></h1><div class="epigraph"><p>EUV 扫描机、投影光学、锡源激光，公开格局是极端集中；交货期与出口规则进入产能方程，与 wph 并列。</p><footer>—— 对照 EUV 工具链集中（ASML、Zeiss、源与激光供应链）的公开产业事实；出口见专门课</footer></div><p><a href="/litho/moore-litho-view">上一课</a>把密度经济接到工具链。缺口是链上有多少家。本课钉供应链集中与单一来源。<a href="/litho/euv-export-control">EUV 出口管制</a> 已谈规则；这里谈结构风险。胶的 PFAS 管制，留给<a href="/litho/pfas-resist-regulation">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>量产 EUV 扫描机由 ASML 交付，投影光学与 Zeiss 深度绑定，源与驱动激光同样高度集中。DUV 浸没竞争略多，但仍寡占。掩模坯、光化检验、pellicle 也各有窄口。单一来源的工程含义：台数上限、维修备件、学习曲线共享、议价、地缘。</p><p>缺口是<strong>可获得性</strong>，不是光学设计。把 capex 当唯一约束，会忽略「有预算但无槽位」。</p>',6)),(t(),r(s,null,{default:e(()=>[o(l,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUD%5B%22%E9%92%B1%3A%20capex%20%E9%A2%84%E7%AE%97%22%5D%20--%3E%20REAL%5B%22%E5%AE%9E%E9%99%85%E8%A3%85%E6%9C%BA%E5%8F%B0%E6%95%B0%22%5D%0A%20%20SLOT%5B%22%E6%A7%BD%E4%BD%8D%3A%20%E4%BA%A4%E8%B4%A7%E6%9C%9F%E6%8E%92%E9%98%9F%22%5D%20--%3E%20REAL%0A%20%20RULE%5B%22%E5%87%BA%E5%8F%A3%E8%A7%84%E5%88%99%3A%20%E8%AE%B8%E5%8F%AF%22%5D%20--%3E%20REAL%0A%20%20REAL%20--%3E%20WPH%5B%22%E5%8F%B0%E6%95%B0%20%C3%97%20wph%20%3D%20%E6%9C%89%E6%95%88%E4%BA%A7%E8%83%BD%22%5D%0A%20%20SLOT%20--%3E%20PLAN%5B%22%E4%B8%8B%E5%8D%95%E6%99%9A%E4%B8%80%E5%B9%B4%20%E8%A3%85%E6%9C%BA%E6%99%9A%E4%B8%80%E5%B9%B4%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p><span class="marginnote">直觉类比：单一来源像全村只有一口井——井水再甜、再稳定，排队长度和旱季配水都由这一口井说了算；你不是没钱打水，是轮不到你打水。「有预算但无槽位」说的就是这种结构性等待。</span></p><p><span class="marginnote">常见误区：以为产能规划只是「今年批多少钱买多少台」。交货期把下单与装机隔开一到数年：今年签的合同决定的是几年后的产能曲线，预算批准那一刻并不产生任何晶圆。</span></p><h3 id="集中也有正面" tabindex="-1">集中也有正面 <a class="header-anchor" href="#集中也有正面" aria-label="Permalink to &quot;集中也有正面&quot;">​</a></h3><p>标准接口、匹配经验、全球备件，降低每厂独自集成的成本。课程既不写成垄断道德剧，也不写成无风险。</p><p><span class="marginnote">中国浸没 DUV 课谈另一条供给。本课对象是领先 EUV 链的集中事实。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规划：交货期当资源。风险：双源仅在仍存在竞争的环节（部分 DUV、胶、部分计量）。合同：服务水平。与匹配：全球同一供应商使 cross-fab 经验可迁移，也使共同模式故障成为可能。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>极紫外工具的资本与知识门槛把潜在进入者挡在外面，集中是结果。物理上可以有第二套源概念（后课 FEL），工业上量产扫描机仍是另一门槛。</p><p><span class="marginnote">「共同模式故障」翻译一下：大家用的是同一家的同一设计，所以同一个缺陷会让所有客户的机器同一时间出同一种病——分工的多样性和冗余在单一来源面前都失效，全球停机风险是相关的，不是各自独立的。</span></p>',10)),(t(),r(s,null,{default:e(()=>[o(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOOL%5B%22EUV%20%E6%89%AB%E6%8F%8F%E6%9C%BA%22%5D%20--%3E%20CONC%5B%22%E9%9B%86%E4%B8%AD%E4%BE%9B%E7%BB%99%22%5D%0A%20%20OPT%5B%22%E6%8A%95%E5%BD%B1%E5%85%89%E5%AD%A6%22%5D%20--%3E%20CONC%0A%20%20SRC%5B%22%E6%BA%90%20%2F%20%E6%BF%80%E5%85%89%22%5D%20--%3E%20CONC%0A%20%20CONC%20--%3E%20LT%5B%22%E4%BA%A4%E8%B4%A7%E6%9C%9F%20%3D%20%E4%BA%A7%E8%83%BD%E5%8F%98%E9%87%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不预测某公司股价。不泄露未公开产能。出口细节指向已有课。</p><p>后课默认：工具可获得性是约束；下一课材料侧的管制（PFAS）同样能卡胶。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>领先 EUV 链高度集中，交货期与备件进入产能方程。</li><li>集中有匹配红利，也有共同模式与地缘风险。</li><li>双源只存在于仍竞争的环节。</li><li>出处：EUV 工具链公开产业格局。</li></ul>',5))])}const T=n(B,[["render",d]]);export{f as __pageData,T as default};
